REF_DIAMETER = 92.0

def get_pokeball_modular_components(target_diameter=None):
    """
    Restituisce la tupla (top_shell, bottom_shell, black_structure, button):
    - top_shell: calotta superiore (Rosso #ee1515)
    - bottom_shell: calotta inferiore (Bianco #ffffff)
    - black_structure: fascia e anello (Nero #1a1a1a)
    - button: bottone centrale (Bianco #ffffff)
    Scalate al diametro desiderato (target_diameter in mm).
    """
    p_top = wkt.loads(WKT_POKEBALL_TOP)
    p_bottom = wkt.loads(WKT_POKEBALL_BOTTOM)
    p_band = wkt.loads(WKT_POKEBALL_BAND)
    p_btn = wkt.loads(WKT_POKEBALL_BUTTON)

    if target_diameter is not None and target_diameter > 1e-4:
        scale = target_diameter / REF_DIAMETER
        p_top = affinity.scale(p_top, xfact=scale, yfact=scale, origin=(0, 0))
        p_bottom = affinity.scale(p_bottom, xfact=scale, yfact=scale, origin=(0, 0))
        p_band = affinity.scale(p_band, xfact=scale, yfact=scale, origin=(0, 0))
        p_btn = affinity.scale(p_btn, xfact=scale, yfact=scale, origin=(0, 0))

    return p_top, p_bottom, p_band, p_btn

def get_pokeball_geometry(target_diameter=None):
    """Restituisce l'unione completa dei 4 componenti della Pokéball."""
    top, bottom, band, btn = get_pokeball_modular_components(target_diameter=target_diameter)
    return unary_union([top, bottom, band, btn])
